def solution(items):
    """Returns the count of elements that appear an odd number of times."""
    from collections import Counter
    return sum(1 for count in Counter(items).values() if count % 2 == 1)

def solution(items):
    """Returns the number of elements that appear exactly once in the list."""
    return sum(1 for x in set(items) if items.count(x) == 1)
